const D = { height:.5, energy:.55, hue:28, speed:1, density:.4, scale:1, x:.5, y:.72, style:'mirage', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;

// ---- cached gradient/heat strip, keyed on size+seed+style+hue-bucket ----
const hueBucket = Math.round(P.hue/12);
const key = width+'x'+height+'|'+P.seed+'|'+P.style+'|'+hueBucket;
if (!S.grad || S.gkey !== key) {
  const gw = 240, gh = 256;
  const g = createGraphics(gw, gh);
  g.colorMode(HSB, 360, 100, 100, 100);
  g.noStroke();
  const ramp = (t) => {
    if (P.style === 'thermal') {
      if (t < .25) return [hw(P.hue+30), 20, 100];
      if (t < .5)  return [hw(P.hue+10), 85, 96];
      if (t < .75) return [hw(P.hue-20), 95, 70];
      return [hw(P.hue-70), 90, 34];
    }
    if (P.style === 'oil') return [hw(P.hue + t*260), 65, 55 + Math.sin(t*10)*20 + 30];
    if (P.style === 'ink') return [hw(P.hue), 10, 20 + (1-t)*55];
    if (P.style === 'scanline') return [hw(P.hue), 55, 30 + (1-t)*55];
    return [hw(P.hue + (1-t)*24), 55 + (1-t)*35, 38 + (1-t)*54];
  };
  for (let y = 0; y < gh; y++) {
    const t = y/gh;
    const c = ramp(t);
    // baked VERTICAL streak structure (high contrast) so horizontal wobble reveals it,
    // plus fine horizontal grain jitter — refracted-background texture.
    for (let x = 0; x < gw; x += 3) {
      const streak = 0.5 + 0.5*Math.sin(x*0.16 + fr((x/9|0)+3)*6.2);            // strong columns
      const streak2 = 0.5 + 0.5*Math.sin(x*0.5 + fr(y*7)*6.2 + fr((x/5|0))*3);   // finer columns
      const vmod = 0.42 + 0.58*(streak*0.65 + streak2*0.35);                     // ~0.42..1.0 contrast
      g.fill(c[0], c[1], c[2]*vmod, 100);
      g.rect(x, y, 3, 1);
    }
  }
  if (P.style === 'scanline') {
    g.fill(0,0,0,100);
    for (let y = 0; y < gh; y += 4) g.rect(0, y, gw, 2);
  }
  S.grad = g; S.gkey = key;
}

const bandH = Math.max(0.06, Math.min(1, P.height)) * height;
const cy = P.y * height;
let top = cy - bandH*0.5;
if (top + bandH > height) top = height - bandH;
if (top < 0) top = 0;
const bandW = width * (0.6 + P.scale*0.55);
const bx = P.x*width - bandW*0.5;

const nStrips = Math.max(24, Math.min(120, Math.round(bandH / Math.max(3, u*0.006))));
const stripH = bandH / nStrips;
const gsH = S.grad.height / nStrips;

// motion: continuous real-time baseline + audio; horizontal wobble + vertical ripple
const amp  = u * (0.02  + P.energy*0.06) * (0.85 + K.swell*0.5 + A.bass*0.9);   // horizontal refraction
const vamp = u * (0.009 + P.energy*0.03) * (0.85 + K.swell*0.4 + A.bass*0.6);   // vertical ripple (reveals ramp)
const freq = 5.5 + P.density*7;
const roll = K.t*(1.1 + P.speed*1.3);        // real-time scroll — never rephases
const srcScroll = (K.t*(0.03 + P.speed*0.02)) % 1;   // gentle source-y drift through the ramp

const blend = (P.style === 'ink') ? BLEND : SCREEN;
const alpha = (P.style === 'ink') ? 60 : (P.style==='scanline'? 64 : 46 + K.intensity*22);

push();
blendMode(blend);
tint(0, 0, 100, alpha);
for (let s = 0; s < nStrips; s++) {
  const y = top + s*stripH;
  const yf = s/nStrips;
  const dx = Math.sin(yf*freq + roll)*amp
           + Math.sin(yf*freq*2.3 - roll*1.7 + 1.3)*amp*0.4
           + Math.sin(K.t*0.35 + yf*3)*amp*0.5;
  const dyv = Math.sin(yf*freq*0.8 - roll*0.9 + 0.6)*vamp
            + Math.sin(K.t*0.7 + yf*5)*vamp*0.7;
  const squash = 1 + Math.sin(yf*freq*0.6 + roll*0.7)*0.05;
  const srcY = ((s/nStrips + srcScroll*0.4) % 1) * S.grad.height * (1 - 1/nStrips);
  image(S.grad, bx+dx, y+dyv, bandW*squash, stripH+1.5, 0, srcY, S.grad.width, gsH);
}
noTint();

// ---- rising heat wisps (density) — continuous upward travel, brighter/larger ----
if (P.density > 0.02) {
  blendMode(SCREEN);
  noStroke();
  const nW = Math.round(P.density * 30) + 4;
  for (let i = 0; i < nW; i++) {
    const wx = bx + fr(i*2+1)*bandW + Math.sin(K.t*(0.5+fr(i)*0.7)+i)*u*0.04;
    const prog = (fr(i*2+2) + K.t*(0.07 + fr(i+9)*0.07)*P.speed) % 1;
    const wy = top + bandH - prog*bandH;
    const life = Math.sin(prog*Math.PI);
    const wv = 45 + life*45 + A.rms*40;
    fill(hw(P.style==='ink'?P.hue:P.hue+16), P.style==='ink'?10:45, wv, (8 + life*20));
    ellipse(wx, wy, u*0.022*P.scale, u*0.06*P.scale*(0.6+life));
  }
}

blendMode(BLEND);
pop();
if (drawingContext) drawingContext.shadowBlur = 0;
